import json
import subprocess
import tempfile
import time
import unittest
from pathlib import Path


REPOSITORY = Path(__file__).resolve().parents[1]
WORKER = REPOSITORY / "bin" / "lease-worker"
POLL_INTERVAL = 0.01
START_TIMEOUT = 3.0
PROCESS_TIMEOUT = 4.0


class LeaseLifecycleTests(unittest.TestCase):
    def setUp(self):
        self._temporary = tempfile.TemporaryDirectory(prefix="lease-lifecycle-")
        self.base = Path(self._temporary.name)
        self.store = self.base / "store"
        self._processes = []

    def tearDown(self):
        diagnostics = []
        for process in self._processes:
            if process.poll() is None:
                process.kill()
            try:
                stdout, stderr = process.communicate(timeout=PROCESS_TIMEOUT)
            except subprocess.TimeoutExpired:
                diagnostics.append(f"pid {process.pid} could not be reaped")
            else:
                if process.returncode is None:
                    diagnostics.append(f"pid {process.pid} has no return code")
                if stderr:
                    diagnostics.append(f"pid {process.pid} stderr: {stderr!r}")
        self._temporary.cleanup()
        if diagnostics:
            self.fail("subprocess cleanup failed: " + "; ".join(diagnostics))

    def worker(self, command, *arguments):
        completed = subprocess.run(
            [str(WORKER), command, *(str(argument) for argument in arguments)],
            cwd=REPOSITORY,
            text=True,
            capture_output=True,
            timeout=PROCESS_TIMEOUT,
            check=False,
        )
        self.assertEqual(
            completed.returncode,
            0,
            f"{command} failed: stdout={completed.stdout!r}, "
            f"stderr={completed.stderr!r}",
        )
        self.assertEqual(
            completed.stderr, "", f"{command} wrote stderr: {completed.stderr!r}"
        )
        try:
            return json.loads(completed.stdout)
        except json.JSONDecodeError as error:
            self.fail(f"{command} returned invalid JSON {completed.stdout!r}: {error}")

    def start_worker(self, command, *arguments, stdin=None):
        process = subprocess.Popen(
            [str(WORKER), command, *(str(argument) for argument in arguments)],
            cwd=REPOSITORY,
            stdin=stdin,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
        )
        self._processes.append(process)
        return process

    def wait_for_path(self, path, process, description):
        deadline = time.monotonic() + START_TIMEOUT
        while time.monotonic() < deadline:
            if path.exists():
                return
            return_code = process.poll()
            if return_code is not None:
                stdout, stderr = process.communicate(timeout=PROCESS_TIMEOUT)
                self.fail(
                    f"{description}: worker exited {return_code} before {path} appeared; "
                    f"stdout={stdout!r}, stderr={stderr!r}"
                )
            time.sleep(POLL_INTERVAL)
        self.fail(
            f"{description}: timed out after {START_TIMEOUT:.1f}s waiting for {path}; "
            f"pid={process.pid}, poll={process.poll()}, tree={self.store_tree()}"
        )

    def finish(self, process, description):
        try:
            stdout, stderr = process.communicate(timeout=PROCESS_TIMEOUT)
        except subprocess.TimeoutExpired:
            self.fail(
                f"{description}: pid {process.pid} did not exit within "
                f"{PROCESS_TIMEOUT:.1f}s; tree={self.store_tree()}"
            )
        self.assertEqual(
            process.returncode,
            0,
            f"{description}: returncode={process.returncode}, "
            f"stdout={stdout!r}, stderr={stderr!r}",
        )
        self.assertEqual(stderr, "", f"{description}: stderr={stderr!r}")
        try:
            return json.loads(stdout)
        except json.JSONDecodeError as error:
            self.fail(f"{description}: invalid JSON {stdout!r}: {error}")

    def store_tree(self):
        if not self.store.exists():
            return []
        result = []
        for path in sorted(self.store.rglob("*")):
            relative = str(path.relative_to(self.store))
            result.append((relative, path.read_text() if path.is_file() else None))
        return result

    def assert_no_owned_residuals(self):
        leases = list((self.store / "leases").glob("*.json"))
        resources = (
            list((self.store / "resources").iterdir())
            if (self.store / "resources").is_dir()
            else []
        )
        waiters = (
            list((self.store / "waiters").iterdir())
            if (self.store / "waiters").is_dir()
            else []
        )
        self.assertEqual(leases, [], f"lease residuals: {self.store_tree()}")
        self.assertEqual(resources, [], f"resource residuals: {self.store_tree()}")
        self.assertEqual(waiters, [], f"waiter residuals: {self.store_tree()}")

    def test_two_worker_handoff_uses_probe_and_gate(self):
        resource = "handoff"
        first = self.start_worker(
            "hold", self.store, resource, "owner-a", 100, 40,
            stdin=subprocess.PIPE,
        )
        self.wait_for_path(
            self.store / "leases" / f"{resource}.json", first, "first owner claim"
        )
        self.assertEqual(self.worker("owner", self.store, resource, 101), {"owner": "owner-a"})

        probe = self.base / "second.ready"
        gate = self.base / "second.go"
        second = self.start_worker(
            "wait", self.store, resource, "owner-b", 102, 40,
            probe, gate, 1.0,
        )
        self.wait_for_path(probe, second, "second worker readiness")
        self.assertEqual(probe.read_text(), "ready\n")
        self.assertIsNone(second.poll(), "second worker passed its gate prematurely")
        self.assertEqual(self.worker("owner", self.store, resource, 102), {"owner": "owner-a"})

        self.assertEqual(
            self.worker("release", self.store, resource, "owner-a"), {"released": True}
        )
        gate.touch()
        self.assertEqual(
            self.finish(second, "gated second worker"),
            {"acquired": True, "owner": "owner-b"},
        )
        self.assertEqual(self.worker("owner", self.store, resource, 103), {"owner": "owner-b"})

        first.stdin.close()
        first.stdin = None
        self.assertEqual(
            self.finish(first, "first holder"), {"acquired": True, "owner": "owner-a"}
        )
        self.assertEqual(
            self.worker("release", self.store, resource, "owner-b"), {"released": True}
        )
        self.assert_no_owned_residuals()

    def test_crashed_owner_expires_and_is_recovered_by_fresh_processes(self):
        resource = "crash-recovery"
        crashed = self.start_worker(
            "hold", self.store, resource, "crashed-owner", 200, 10,
            stdin=subprocess.PIPE,
        )
        self.wait_for_path(
            self.store / "leases" / f"{resource}.json", crashed, "crash owner claim"
        )
        self.assertEqual(
            self.worker("owner", self.store, resource, 209), {"owner": "crashed-owner"}
        )

        crashed.kill()
        stdout, stderr = crashed.communicate(timeout=PROCESS_TIMEOUT)
        self.assertEqual(crashed.returncode, -9, (stdout, stderr))
        self.assertEqual(stderr, "")

        self.assertEqual(self.worker("owner", self.store, resource, 209), {"owner": "crashed-owner"})
        self.assertEqual(self.worker("owner", self.store, resource, 210), {"owner": None})
        self.assertEqual(
            self.worker("claim", self.store, resource, "restarted-owner", 210, 10),
            {"acquired": True, "owner": "restarted-owner"},
        )
        self.assertEqual(
            self.worker("release", self.store, resource, "restarted-owner"),
            {"released": True},
        )
        self.assert_no_owned_residuals()

    def test_overlapping_contenders_have_only_one_live_owner(self):
        resource = "contended"
        first_probe = self.base / "owner-left.ready"
        first_gate = self.base / "owner-left.go"
        first = self.start_worker(
            "wait", self.store, resource, "owner-left", 300, 30,
            first_probe, first_gate, 0.5,
        )
        self.wait_for_path(first_probe, first, "owner-left readiness")
        first_gate.touch()
        self.assertEqual(
            self.finish(first, "owner-left contention"),
            {"acquired": True, "owner": "owner-left"},
        )

        second_probe = self.base / "owner-right.ready"
        second_gate = self.base / "owner-right.go"
        second = self.start_worker(
            "wait", self.store, resource, "owner-right", 329, 30,
            second_probe, second_gate, 0.5,
        )
        self.wait_for_path(second_probe, second, "owner-right readiness")
        self.assertIsNone(second.poll(), "owner-right passed its gate prematurely")
        self.assertEqual(
            self.worker("owner", self.store, resource, 329), {"owner": "owner-left"}
        )
        second_gate.touch()
        self.assertEqual(
            self.finish(second, "owner-right contention"),
            {"acquired": False, "owner": None},
        )
        self.assertEqual(
            self.worker("owner", self.store, resource, 329), {"owner": "owner-left"}
        )
        self.assertEqual(
            self.worker("claim", self.store, resource, "owner-right", 329, 30),
            {"acquired": False, "owner": None},
        )
        self.assertEqual(
            self.worker("release", self.store, resource, "owner-left"), {"released": True}
        )
        self.assert_no_owned_residuals()

    def test_cleanup_is_exact_and_preserves_peer_prefix_resource(self):
        target = "job"
        peer = "job-peer"
        self.assertEqual(
            self.worker("claim", self.store, target, "target-owner", 400, 20),
            {"acquired": True, "owner": "target-owner"},
        )
        self.assertEqual(
            self.worker("claim", self.store, peer, "peer-owner", 400, 20),
            {"acquired": True, "owner": "peer-owner"},
        )
        sentinel = self.store / "resources" / peer / "peer.sentinel"
        sentinel.write_text("preserve exactly\n")
        peer_lease = self.store / "leases" / f"{peer}.json"
        peer_before = (peer_lease.read_bytes(), sentinel.read_bytes())

        self.assertEqual(
            self.worker("release", self.store, target, "not-the-owner"),
            {"released": False},
        )
        self.assertEqual(self.worker("owner", self.store, target, 401), {"owner": "target-owner"})
        self.assertEqual(
            self.worker("release", self.store, target, "target-owner"), {"released": True}
        )
        self.assertFalse((self.store / "leases" / f"{target}.json").exists())
        self.assertFalse((self.store / "resources" / target).exists())
        self.assertEqual((peer_lease.read_bytes(), sentinel.read_bytes()), peer_before)
        self.assertEqual(self.worker("owner", self.store, peer, 401), {"owner": "peer-owner"})

        self.assertEqual(
            self.worker("release", self.store, peer, "peer-owner"), {"released": True}
        )
        self.assertFalse(sentinel.exists())
        self.assert_no_owned_residuals()


if __name__ == "__main__":
    unittest.main()
